/* Central UP v0.2: regras e controles da demonstração local. */
const defaults=()=>({Entrega:{base:4,km:1.8,minute:0.15,minimum:8}});
const roundMoney=n=>Math.round((n+Number.EPSILON)*100)/100;
const timestamp=()=>new Date().toLocaleString('pt-BR');
function deliveryCode(){const values=new Uint32Array(1);crypto.getRandomValues(values);return String(1000+values[0]%9000)}
function migrate(){state.tariffs??=defaults();state.version=2;state.next=Math.max(Number(state.next)||1047,...state.services.map(s=>(Number(s.id.replace('VP-',''))||0)+1));for(const s of state.services){s.events??=[];if(s.type==='Entrega')s.deliveryCode??=deliveryCode();} }
migrate();
const oldRender=render;
render=function(){migrate();oldRender();$('tariff-fields').innerHTML=Object.entries(state.tariffs).map(([type,t])=>'<div class="tariff-group"><h3>'+esc(type)+'</h3><div class="tariff-grid">'+[['base','Taxa base (R$)'],['km','Por km (R$)'],['minute','Por minuto (R$)'],['minimum','Valor mínimo (R$)']].map(([key,label])=>'<label>'+label+'<input name="'+type+'-'+key+'" value="'+t[key]+'" type="number" min="0" max="1000" step="0.01" required></label>').join('')+'</div></div>').join('');};
log=function(text){state.audit.unshift({text,time:timestamp(),actor:'Operador da central (demonstração)'});};
function event(s,text){s.events.push(timestamp()+' · '+text);log(s.id+' · '+text)}
function quote(type,distance,minutes){const t=state.tariffs[type];if(!t||!Number.isFinite(distance)||distance<=0||distance>500||!Number.isFinite(minutes)||minutes<1||minutes>1440)throw Error('Informe distância entre 0,1 e 500 km e tempo entre 1 e 1.440 minutos.');return {price:roundMoney(Math.max(t.minimum,t.base+t.km*distance+t.minute*minutes)),snapshot:{...t,distance,minutes,type,calculatedAt:new Date().toISOString()}}}
function updateQuote(){try{const q=quote($('create-type').value,Number($('create-distance').value),Number($('create-minutes').value));$('create-price').value=q.price.toFixed(2);$('quote-summary').textContent='Estimativa: '+money(q.price)+' · Valores de teste. Distância e tempo não são calculados por GPS.'}catch(e){$('create-price').value='';$('quote-summary').textContent=e.message}}
['create-type','create-distance','create-minutes'].forEach(id=>$(id).addEventListener('input',updateQuote));
$('new-service').onclick=()=>{updateQuote();$('create-dialog').showModal()};
function createService(input){const {type,payment}=input,client=String(input.client||'').trim(),origin=String(input.origin||'').trim(),destination=String(input.destination||'').trim();if(!['Entrega'].includes(type)||!['Pix','Dinheiro','Cartão'].includes(payment)||!client||!origin||!destination||client.length>70||origin.length>140||destination.length>140)throw Error('Preencha os dados da solicitação corretamente.');const q=quote(type,Number(input.distance),Number(input.minutes));const s={id:'VP-'+state.next++,type,client,origin,destination,payment,price:q.price,tariffSnapshot:q.snapshot,status:'Aguardando parceiro',partner:null,createdAt:new Date().toISOString(),events:[]};if(type==='Entrega')s.deliveryCode=deliveryCode();state.services.unshift(s);event(s,'Solicitação criada pela central · '+money(q.price));save();return s}
$('create-form').onsubmit=e=>{e.preventDefault();try{const s=createService(Object.fromEntries(new FormData(e.target)));$('create-dialog').close();e.target.reset();updateQuote();toast('Solicitação criada.');detail(s.id)}catch(error){toast(error.message)}};
$('tariff-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),proposed={};for(const type of ['Entrega']){proposed[type]={};for(const key of ['base','km','minute','minimum']){const n=Number(f.get(type+'-'+key));if(!Number.isFinite(n)||n<0||n>1000){toast('Use valores entre R$ 0,00 e R$ 1.000,00.');return}proposed[type][key]=roundMoney(n)}}state.tariffs=proposed;log('Tarifas de teste atualizadas: '+JSON.stringify(proposed));save();updateQuote();toast('Tarifas salvas para novas solicitações.');};
document.querySelector('[data-view="tariffs"]').onclick=()=>{document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='tariffs'));document.querySelectorAll('.section').forEach(s=>s.classList.toggle('active',s.id==='tariffs'));$('title').textContent='Tarifas';};
const originalConfirm=confirmAction;
confirmAction=function(title,text,fn,requiresReason=false){$('action-reason').value='';$('reason-error').textContent='';$('action-reason').hidden=!requiresReason;$('reason-label').hidden=!requiresReason;originalConfirm(title,text,()=>{fn($('action-reason').value.trim())});$('confirm-yes').onclick=()=>{if(requiresReason&&$('action-reason').value.trim().length<3){$('reason-error').textContent='Informe um motivo com pelo menos 3 caracteres.';$('action-reason').focus();return}const action=pendingConfirm;pendingConfirm=null;$('confirm-dialog').close();try{action?.()}catch(e){toast(e.message)}};};
function reassign(id,pid,reason){const s=state.services.find(s=>s.id===id);if(!s||finished(s)||!s.partner||!['Aceita','A caminho','No local'].includes(s.status))throw Error('Reatribuição permitida somente antes da coleta.');if(typeof reason!=='string'||reason.trim().length<3)throw Error('Informe o motivo da reatribuição.');const p=eligible(s).find(p=>p.id===pid);if(!p)throw Error('O novo parceiro precisa estar disponível e ser compatível.');const old=state.partners.find(p=>p.id===s.partner);s.partner=p.id;s.status='Aceita';event(s,'Reatribuído de '+old.name+' para '+p.name+' · Motivo: '+reason.trim());save();refreshDetail();toast('Parceiro reatribuído.');return {id,status:s.status,partner:p.name}}
assign=function(id,pid){const s=state.services.find(x=>x.id===id);if(!s||finished(s)||s.partner)throw Error('Este serviço não está disponível para despacho.');const p=eligible(s).find(x=>x.id===pid);if(!p)throw Error('Parceiro indisponível ou modalidade incompatível.');s.partner=pid;s.status='Aceita';event(s,'Atribuído a '+p.name);save();refreshDetail();toast('Parceiro atribuído na demonstração.');return {id,status:s.status,partner:p.name}};
advance=function(id,code){const s=state.services.find(x=>x.id===id);if(!s||!s.partner||finished(s))throw Error('Serviço indisponível para atualização.');const idx=paths[s.type].indexOf(s.status);if(idx<0||idx>=paths[s.type].length-1)throw Error('Transição inválida.');const next=paths[s.type][idx+1];if(next==='Entregue'){if(String(code||'').trim()!==s.deliveryCode)throw Error('Código de confirmação incorreto. A entrega continua em rota.');s.proof={confirmedAt:new Date().toISOString(),partner:s.partner,actor:'Operador da central (demonstração)',method:'Código de confirmação'}}s.status=next;event(s,'Status atualizado para '+next+(next==='Entregue'?' · Recebimento confirmado por código':''));save();refreshDetail();toast(next==='Entregue'?'Entrega confirmada por código.':'Status atualizado.');return {id,status:s.status}};
cancel=function(id,reason){const s=state.services.find(x=>x.id===id);if(!s||finished(s))throw Error('Este serviço já foi encerrado.');if(typeof reason!=='string'||reason.trim().length<3)throw Error('Informe o motivo do cancelamento.');s.status='Cancelada';s.cancelReason=reason.trim();event(s,'Cancelado · Motivo: '+s.cancelReason);save();refreshDetail();toast('Solicitação cancelada.');};
detail=function(id){current=id;const s=state.services.find(x=>x.id===id);if(!s)return;const p=state.partners.find(x=>x.id===s.partner),candidates=eligible(s),idx=paths[s.type].indexOf(s.status),next=paths[s.type][idx+1],canReassign=!!s.partner&&!finished(s)&&['Aceita','A caminho','No local'].includes(s.status);$('detail-title').textContent=s.id+' · '+s.type;const selector=(field)=>'<select id="'+field+'" class="status-select">'+(candidates.length?candidates.map(p=>'<option value="'+p.id+'">'+esc(p.name)+' · '+esc(p.vehicle)+'</option>').join(''):'<option value="">Nenhum parceiro disponível</option>')+'</select>';
let content='<p>'+esc(s.client)+' · '+badge(s.status)+'</p><ol class="steps" aria-label="Etapas do serviço">'+['Aguardando parceiro',...paths[s.type]].map((step,i)=>'<li class="'+(step===s.status?'current':idx>=0&&i<=idx?'passed':'')+'">'+esc(step)+'</li>').join('')+'</ol><div class="detail-grid"><div><label>Origem / coleta</label>'+esc(s.origin)+'</div><div><label>Destino</label>'+esc(s.destination)+'</div><div><label>Valor e pagamento</label>'+money(s.price)+' · '+esc(s.payment)+'</div><div><label>Parceiro</label>'+esc(p?.name||'Ainda não atribuído')+'</div></div>';
if(s.tariffSnapshot){const t=s.tariffSnapshot;content+='<p class="notice">Tarifa preservada: '+t.distance+' km · '+t.minutes+' min · Taxa base '+money(t.base)+' + '+money(t.km)+'/km + '+money(t.minute)+'/min · Mínimo '+money(t.minimum)+'.</p>'}else content+='<p class="notice">Valor de exemplo da primeira versão; sem cálculo de tarifa registrado.</p>';
if(!finished(s)&&!s.partner)content+='<label for="dispatch-partner">Parceiro disponível</label>'+selector('dispatch-partner')+'<div class="actions"><button class="primary" id="dispatch" '+(!candidates.length?'disabled':'')+'>Atribuir parceiro</button></div>';
if(!finished(s)&&s.partner&&next){if(next==='Entregue')content+='<div class="proof"><label for="delivery-code">Código de recebimento</label><input id="delivery-code" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" autocomplete="off" placeholder="4 dígitos"><p class="notice">Para testar, use o código fictício <strong>'+esc(s.deliveryCode)+'</strong>. Em produção, o destinatário receberá o código.</p></div>';content+='<div class="actions"><button class="primary" id="advance">'+(next==='Entregue'?'Confirmar entrega':'Avançar para: '+esc(next))+'</button></div>'}
if(canReassign)content+='<h3>Reatribuir parceiro</h3><p class="notice">O serviço voltará para Aceita. O parceiro atual ficará livre.</p><label for="replacement-partner">Novo parceiro</label>'+selector('replacement-partner')+'<div class="actions"><button id="reassign" '+(!candidates.length?'disabled':'')+'>Reatribuir com motivo</button></div>';
if(!finished(s))content+='<div class="actions"><button id="cancel-service">Cancelar com motivo</button></div>';
if(s.proof)content+='<div class="proof"><strong>Recebimento confirmado</strong><p class="notice">'+esc(new Date(s.proof.confirmedAt).toLocaleString('pt-BR'))+' · Parceiro: '+esc(state.partners.find(p=>p.id===s.proof.partner)?.name||s.proof.partner)+' · '+esc(s.proof.actor)+'</p></div>';
content+='<h3>Histórico do serviço</h3><ol class="history">'+s.events.map(e=>'<li>'+esc(e)+'</li>').join('')+'</ol><p class="notice">Atualizações manuais e simuladas. Sem GPS ou ofertas reais.</p>';$('detail').innerHTML=content;if(!$('detail-dialog').open)$('detail-dialog').showModal();const guarded=fn=>()=>{try{fn()}catch(e){toast(e.message)}};if($('dispatch'))$('dispatch').onclick=guarded(()=>assign(s.id,$('dispatch-partner').value));if($('advance'))$('advance').onclick=guarded(()=>advance(s.id,$('delivery-code')?.value));if($('cancel-service'))$('cancel-service').onclick=()=>confirmAction('Cancelar solicitação','O serviço '+s.id+' será cancelado. Registre o motivo para consulta no histórico.',reason=>cancel(s.id,reason),true);if($('reassign'))$('reassign').onclick=()=>{const pid=$('replacement-partner').value;confirmAction('Reatribuir parceiro','O serviço '+s.id+' será atribuído ao parceiro selecionado.',reason=>reassign(s.id,pid,reason),true)};
};
function csvCell(value){let v=String(value??'');if(/^[\s]*[=+\-@]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'}
function servicesCsv(){const q=$('search').value.toLocaleLowerCase('pt-BR'),type=$('type-filter').value,status=$('status-filter').value;const rows=state.services.filter(s=>(!type||s.type===type)&&(!status||s.status===status)&&[s.id,s.client,s.origin,s.destination].join(' ').toLocaleLowerCase('pt-BR').includes(q));return '\uFEFF'+[['Código','Serviço','Cliente','Origem','Destino','Status','Parceiro','Valor (R$)','Pagamento','Motivo de cancelamento'],...rows.map(s=>[s.id,s.type,s.client,s.origin,s.destination,s.status,state.partners.find(p=>p.id===s.partner)?.name||'',s.price.toFixed(2).replace('.',','),s.payment,s.cancelReason||''])].map(row=>row.map(csvCell).join(';')).join('\r\n')}
$('export-services').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([servicesCsv()],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='vuppi-entregas-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exportação dos serviços filtrados preparada.');};
$('reset').onclick=()=>confirmAction('Reiniciar demonstração','As solicitações, tarifas e o histórico deste navegador serão substituídos pelos dados iniciais.',()=>{state=seed();migrate();save();updateQuote();toast('Demonstração reiniciada.');});
window.addEventListener('storage',e=>{if(e.key===(window.UP_STATE_KEY || 'vuppi-delivery-demo-v3')&&e.newValue){try{const incoming=JSON.parse(e.newValue);if(!Array.isArray(incoming.services)||!Array.isArray(incoming.partners)||!Array.isArray(incoming.audit))return;state=incoming;migrate();render();if($('detail-dialog').open)refreshDetail();toast('Demonstração atualizada a partir de outra aba.')}catch{}}});
render();updateQuote();
